package org.deeptimeline.app
import android.app.Dialog
import android.text.Editable
import android.text.TextWatcher
import android.view.View
import android.view.ViewGroup
import android.view.WindowManager
import android.widget.BaseAdapter
import android.widget.LinearLayout
import android.widget.ListView
import android.widget.TextView
import java.util.Locale
class EventSearch(private val activity:MainActivity,private val events:List<TimelineEvent>,visibleIds:Set<String>,private val onChoose:(TimelineEvent)->Unit){private val dialog=Dialog(activity);private val currentVisible=visibleIds;private val matches=ArrayList<TimelineEvent>();private val root=activity.column();private val query=activity.field("","Search event name or date");private val count=activity.label("",13f);private val listing=ListView(activity);private val adapter=object:BaseAdapter(){override fun getCount():Int=matches.size;override fun getItem(position:Int):Any=matches[position];override fun getItemId(position:Int):Long=position.toLong();override fun getView(position:Int,convertView:View?,parent:ViewGroup):View{val event=matches[position];val wrapper=(convertView as? LinearLayout)?:activity.column();wrapper.removeAllViews();wrapper.setPadding(activity.dp(9),activity.dp(5),activity.dp(8),activity.dp(5));wrapper.add(activity.label(event.title,16f));val state=if(event.id in currentVisible)"VISIBLE" else "HIDDEN AT CURRENT SCALE";wrapper.add(activity.label("${event.civil.replace('T',' ')} · $state · ${VisibilityScale.description(event.maxScaleAmount,event.maxScaleUnit)}",11f));return wrapper}};init{root.setPadding(activity.dp(8),activity.dp(5),activity.dp(8),activity.dp(5));val header=activity.row();header.add(activity.label("SEARCH ALL EVENTS",18f),0,-2,1f);header.add(activity.action("X"){dialog.dismiss()},activity.dp(48),activity.dp(44));root.add(header);root.add(activity.label("Search includes hidden events. Tap a result to center it and zoom in if its scale limit requires it.",12f));root.add(query,-1,activity.dp(49));root.add(count);listing.adapter=adapter;listing.setBackgroundColor(BLACK);listing.isFastScrollEnabled=true;listing.setOnItemClickListener{_,_,position,_->val chosen=matches[position];dialog.dismiss();onChoose(chosen)};root.add(listing,-1,0,1f);root.add(activity.action("CANCEL"){dialog.dismiss()},-1,activity.dp(46));query.addTextChangedListener(object:TextWatcher{override fun beforeTextChanged(s:CharSequence?,start:Int,count:Int,after:Int){};override fun onTextChanged(s:CharSequence?,start:Int,before:Int,count:Int){filter(s.toString())};override fun afterTextChanged(s:Editable?){}});filter("");dialog.setContentView(root);dialog.window?.setBackgroundDrawableResource(android.R.color.black);dialog.window?.setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE)};private fun filter(raw:String){val terms=raw.lowercase(Locale.ROOT).trim().split(Regex("\\s+")).filter{it.isNotBlank()};matches.clear();for(event in events){val text=(event.title+" "+event.civil+" "+event.mode).lowercase(Locale.ROOT);if(terms.all{text.contains(it)})matches.add(event)};adapter.notifyDataSetChanged();count.text="${matches.size} matching / ${events.size} total · ${matches.count{it.id !in currentVisible}} hidden at current zoom"};fun show(){dialog.show();dialog.window?.setLayout((activity.resources.displayMetrics.widthPixels*0.98).toInt(),(activity.resources.displayMetrics.heightPixels*0.85).toInt())}}
